 import java.time.LocalDate;

 /** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
@@ -12,6 +14,10 @@ public record ReservationReceipt(
         long reservationId,
         String guestName,
         String guestCpf,
+        String companyCnpj,
+        String companyName,
+        String guestPassport,
+        String guestCountry,
